import type { SpeechProvider } from '@xsai-ext/providers/utils'

import { errorMessageFrom } from '@moeru/std'

export const FRIEREN_DUAL_SPEECH_PROVIDER_ID = 'frieren-dual-speech'
export const FRIEREN_DUAL_SPEECH_DEFAULT_BASE_URL = 'http://192.168.50.136:8010/v1/'
export const FRIEREN_DUAL_SPEECH_DEFAULT_API_KEY = 'dummy'
export const FRIEREN_DUAL_SPEECH_DEFAULT_VOICE = 'frieren'
export const FRIEREN_DUAL_SPEECH_DEFAULT_SPEED = 0.95
export const FRIEREN_DUAL_SPEECH_DEFAULT_MODEL = FRIEREN_DUAL_SPEECH_PROVIDER_ID

export interface FrierenDualSpeechConfig {
  apiKey?: string
  baseUrl?: string
  voice?: string
  speed?: number
}

export interface FrierenDualSpeechApiResponse {
  display_text?: string
  speech_text?: string
  audio_base64?: string
  audio_format?: string
  media_type?: string
}

export interface SpeechGenerationResult {
  audio: ArrayBuffer
  displayText?: string
  speechText?: string
  audioFormat?: string
  mediaType?: string
}

export type SpeechGenerationOutput = ArrayBuffer | SpeechGenerationResult

function normalizeBaseUrl(value: unknown): string {
  let baseUrl = typeof value === 'string' ? value.trim() : ''
  if (!baseUrl)
    baseUrl = FRIEREN_DUAL_SPEECH_DEFAULT_BASE_URL
  if (!baseUrl.endsWith('/'))
    baseUrl += '/'
  return baseUrl
}

function normalizeApiKey(value: unknown): string {
  const apiKey = typeof value === 'string' ? value.trim() : ''
  return apiKey || FRIEREN_DUAL_SPEECH_DEFAULT_API_KEY
}

function normalizeVoice(value: unknown): string {
  const voice = typeof value === 'string' ? value.trim() : ''
  return voice || FRIEREN_DUAL_SPEECH_DEFAULT_VOICE
}

function normalizeSpeed(value: unknown): number {
  if (typeof value === 'number' && Number.isFinite(value) && value > 0)
    return value

  if (typeof value === 'string') {
    const parsed = Number.parseFloat(value)
    if (Number.isFinite(parsed) && parsed > 0)
      return parsed
  }

  return FRIEREN_DUAL_SPEECH_DEFAULT_SPEED
}

export function normalizeSpeechGenerationResult(result: SpeechGenerationOutput): SpeechGenerationResult {
  return result instanceof ArrayBuffer
    ? { audio: result }
    : result
}

function inferMediaType(result: Pick<SpeechGenerationResult, 'audioFormat' | 'mediaType'>): string {
  if (result.mediaType)
    return result.mediaType

  switch (result.audioFormat) {
    case 'wav':
      return 'audio/wav'
    case 'ogg':
      return 'audio/ogg'
    case 'aac':
      return 'audio/aac'
    case 'mp3':
    default:
      return 'audio/mpeg'
  }
}

export function createAudioBlobFromSpeechResult(result: SpeechGenerationOutput): Blob {
  const normalized = normalizeSpeechGenerationResult(result)
  return new Blob([normalized.audio], { type: inferMediaType(normalized) })
}

function decodeBase64Audio(base64: string): Uint8Array {
  const normalized = base64.trim()
  if (!normalized) {
    throw new Error('Frieren Dual Speech returned an empty audio_base64 payload.')
  }

  try {
    if (typeof globalThis.atob === 'function') {
      const binary = globalThis.atob(normalized)
      const bytes = new Uint8Array(binary.length)
      for (let index = 0; index < binary.length; index += 1)
        bytes[index] = binary.charCodeAt(index)
      return bytes
    }

    return Uint8Array.from(Buffer.from(normalized, 'base64'))
  }
  catch (error) {
    throw new Error(`Frieren Dual Speech returned invalid audio_base64: ${errorMessageFrom(error) ?? 'Unknown decode error.'}`)
  }
}

function toArrayBuffer(bytes: Uint8Array): ArrayBuffer {
  const arrayBuffer = new ArrayBuffer(bytes.byteLength)
  new Uint8Array(arrayBuffer).set(bytes)
  return arrayBuffer
}

function createAuthHeaders(apiKey: string): HeadersInit {
  return apiKey
    ? {
        Authorization: `Bearer ${apiKey}`,
      }
    : {}
}

export async function requestFrierenDualSpeech(
  config: FrierenDualSpeechConfig,
  input: string,
  overrides: Partial<Pick<FrierenDualSpeechConfig, 'voice' | 'speed'>> = {},
): Promise<SpeechGenerationResult> {
  const baseUrl = normalizeBaseUrl(config.baseUrl)
  const apiKey = normalizeApiKey(config.apiKey)
  const voice = normalizeVoice(overrides.voice ?? config.voice)
  const speed = normalizeSpeed(overrides.speed ?? config.speed)

  const response = await fetch(new URL('dual/speech', baseUrl), {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      ...createAuthHeaders(apiKey),
    },
    body: JSON.stringify({
      input,
      voice,
      response_format: 'mp3',
      speed,
    }),
  })

  if (!response.ok) {
    const reason = await response.text().catch(() => '')
    throw new Error(`Frieren Dual Speech request failed: HTTP ${response.status} ${response.statusText}${reason ? ` - ${reason}` : ''}`)
  }

  const payload = await response.json() as FrierenDualSpeechApiResponse

  if (!payload.audio_base64) {
    throw new Error('Frieren Dual Speech response is missing audio_base64.')
  }

  const audioBytes = decodeBase64Audio(payload.audio_base64)
  if (audioBytes.byteLength === 0) {
    throw new Error('Frieren Dual Speech returned empty decoded audio data.')
  }

  return {
    audio: toArrayBuffer(audioBytes),
    displayText: payload.display_text?.trim() || undefined,
    speechText: payload.speech_text?.trim() || undefined,
    audioFormat: payload.audio_format?.trim() || undefined,
    mediaType: payload.media_type?.trim() || undefined,
  }
}

function createFrierenDualSpeechFetch(config: FrierenDualSpeechConfig) {
  return async (_input: RequestInfo | URL, init?: RequestInit): Promise<Response> => {
    if (!init?.body || typeof init.body !== 'string')
      throw new Error('Invalid Frieren Dual Speech request body.')

    const requestBody = JSON.parse(init.body) as {
      input?: string
      voice?: string
      speed?: number
    }

    const result = await requestFrierenDualSpeech(config, requestBody.input ?? '', {
      voice: requestBody.voice,
      speed: requestBody.speed,
    })

    return new Response(createAudioBlobFromSpeechResult(result), {
      status: 200,
      headers: {
        'Content-Type': inferMediaType(result),
      },
    })
  }
}

export function createFrierenDualSpeechProvider(config: FrierenDualSpeechConfig): SpeechProvider {
  const normalizedConfig = {
    apiKey: normalizeApiKey(config.apiKey),
    baseUrl: normalizeBaseUrl(config.baseUrl),
    voice: normalizeVoice(config.voice),
    speed: normalizeSpeed(config.speed),
  }

  return {
    speech: () => {
      return {
        baseURL: normalizedConfig.baseUrl,
        model: FRIEREN_DUAL_SPEECH_DEFAULT_MODEL,
        fetch: createFrierenDualSpeechFetch(normalizedConfig),
      }
    },
  }
}
